package za.ac.smartpantrymanager.database;
import android.content.*;import android.database.Cursor;import android.database.sqlite.*;
public class DatabaseHelper extends SQLiteOpenHelper { public DatabaseHelper(Context c){super(c,"smart_pantry.db",null,1);} public void onCreate(SQLiteDatabase d){d.execSQL("CREATE TABLE pantry_items(id INTEGER PRIMARY KEY AUTOINCREMENT,ingredient_name TEXT NOT NULL,quantity REAL NOT NULL,unit TEXT NOT NULL,expiry_date TEXT)");d.execSQL("CREATE TABLE recipes(id INTEGER PRIMARY KEY AUTOINCREMENT,recipe_name TEXT NOT NULL,ingredients TEXT NOT NULL,quantities TEXT NOT NULL,instructions TEXT NOT NULL)");String[][] r={{"Vegetable Omelette","egg,tomato,onion","2,1,1","Whisk eggs. Cook tomato and onion. Add eggs."},{"Tomato Pasta","pasta,tomato,garlic","200,2,1","Boil pasta. Cook tomato and garlic. Combine."},{"Fried Rice","rice,egg,onion","200,2,1","Cook onion. Add rice and egg. Stir-fry."},{"Chicken Stir Fry","chicken,onion,pepper","200,1,1","Cook chicken. Add vegetables and stir-fry."},{"Potato Curry","potato,onion,tomato","300,1,2","Cook ingredients with spices until tender."},{"Tuna Sandwich","bread,tuna,tomato","2,1,1","Fill bread with tuna and tomato."},{"Vegetable Soup","carrot,potato,onion","2,2,1","Simmer vegetables until soft."},{"Egg Fried Rice","rice,egg,carrot","200,2,1","Stir-fry rice with egg and carrot."},{"Tomato Salad","tomato,onion","2,1","Chop and mix."},{"Chicken Salad","chicken,lettuce,tomato","200,2,1","Cook chicken and combine with vegetables."},{"Garlic Bread","bread,garlic,butter","2,1,1","Spread garlic butter and toast."},{"Pancakes","flour,milk,egg","200,250,2","Mix batter and cook."},{"Scrambled Eggs","egg,butter","2,1","Whisk eggs and cook with butter."},{"Pasta Primavera","pasta,carrot,pepper","200,1,1","Boil pasta and saute vegetables."},{"Potato Omelette","potato,egg,onion","200,3,1","Cook potato and onion, add eggs."},{"Rice and Beans","rice,beans,tomato","200,200,1","Cook rice and combine with beans."},{"Vegetable Curry","potato,carrot,onion","200,2,1","Cook vegetables with curry spices."},{"Grilled Cheese Sandwich","bread,cheese,butter","2,2,1","Butter bread, add cheese and grill."},{"Banana Pancakes","banana,flour,egg","2,150,2","Mash banana, mix batter and cook."},{"Chicken Wrap","chicken,lettuce,tomato","200,2,1","Cook chicken and wrap with vegetables."}};for(String[]x:r){ContentValues v=new ContentValues();v.put("recipe_name",x[0]);v.put("ingredients",x[1]);v.put("quantities",x[2]);v.put("instructions",x[3]);d.insert("recipes",null,v);}}public void onUpgrade(SQLiteDatabase d,int a,int b){} public long addPantryItem(String n,double q,String u,String e){ContentValues v=new ContentValues();v.put("ingredient_name",n);v.put("quantity",q);v.put("unit",u);v.put("expiry_date",e);return getWritableDatabase().insert("pantry_items",null,v);}public Cursor getAllPantryItems(){return getReadableDatabase().query("pantry_items",null,null,null,null,null,"ingredient_name ASC");}public int updatePantryItem(int id,String n,double q,String u,String e){ContentValues v=new ContentValues();v.put("ingredient_name",n);v.put("quantity",q);v.put("unit",u);v.put("expiry_date",e);return getWritableDatabase().update("pantry_items",v,"id=?",new String[]{""+id});}public int deletePantryItem(int id){return getWritableDatabase().delete("pantry_items","id=?",new String[]{""+id});}public Cursor getAllRecipes(){return getReadableDatabase().query("recipes",null,null,null,null,null,"recipe_name ASC");}}
